Problem:
A gas company can transport gas using a pipeline or by train. A pipeline can carry 8000 units of gas and a train can carry 2000 units of gas every day. Due to recent environmental changes, the number of trains used must be at least twice as many as the number of pipelines. If at least 1000000 units of gas needs to be transported every day, minimize the total number of pipelines and trains needed.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "pipelines",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "trains",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "pipelines",
     "coef": 1.0
    },
    {
     "var": "trains",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "trains_at_least_twice_pipelines",
    "terms": [
     {
      "var": "trains",
      "coef": 1.0
     },
     {
      "var": "pipelines",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "gas_transport_requirement",
    "terms": [
     {
      "var": "pipelines",
      "coef": 8000.0
     },
     {
      "var": "trains",
      "coef": 2000.0
     }
    ],
    "sense": ">=",
    "rhs": 1000000.0
   }
  ]
 },
 "facts": {
  "objective": 251.0,
  "values": {
   "pipelines": 83.0,
   "trains": 168.0
  },
  "binding": [
   "gas_transport_requirement"
  ],
  "slack": {
   "trains_at_least_twice_pipelines": 2.0,
   "gas_transport_requirement": 0.0
  },
  "shadow_prices": null
 }
}
